const scope = new URL(self.registration.scope);
let foreground = 0, quietSince = Date.now(), warming = null;

self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', event => event.waitUntil((async () => {
  for (const key of await caches.keys()) if (key.startsWith('sparky-') && key !== CACHE) await caches.delete(key);
  await self.clients.claim();
})()));

// The ?v= version stays in the key: an older worker must never answer a newer file with its own
// copy (old code on a new page stopped the game from loading). Other query parts are dropped.
const keyFor = url => { const u = new URL(url), v = u.searchParams.get('v'); u.search = v ? '?v=' + v : ''; u.hash = ''; return u.href; };

async function rangeResponse(response, range) {
  const body = await response.arrayBuffer(), size = body.byteLength;
  const m = /bytes=(\d*)-(\d*)/.exec(range || '');
  let start = m && m[1] !== '' ? +m[1] : 0, end = m && m[2] !== '' ? +m[2] : size - 1;
  if (m && m[1] === '' && m[2] !== '') { start = Math.max(0, size - +m[2]); end = size - 1; }
  end = Math.min(end, size - 1);
  if (start >= size || start > end) return new Response(null, { status: 416, headers: { 'Content-Range': `bytes */${size}` } });
  return new Response(body.slice(start, end + 1), { status: 206, headers: { 'Content-Type': response.headers.get('Content-Type') || 'audio/mpeg', 'Content-Range': `bytes ${start}-${end}/${size}`, 'Content-Length': String(end - start + 1), 'Accept-Ranges': 'bytes' } });
}

async function fromNetwork(request, key) {
  const response = request.mode === 'navigate' ? await fetch(request) : await fetch(request.headers.has('range') ? key : request, { cache: 'no-cache' });
  if (response.ok && response.status === 200) {
    const copy = response.clone();
    caches.open(CACHE).then(cache => cache.put(key, copy)).catch(() => {});
  }
  return response;
}

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== scope.origin || !url.pathname.startsWith(scope.pathname)) return;
  const key = keyFor(request.url);
  event.respondWith((async () => {
    foreground++;
    try {
      // Pages: try the network first so a new build is picked up; fall back to the device.
      if (request.mode === 'navigate') {
        try { return await fromNetwork(request, key); } catch { return (await caches.match(key)) || Response.error(); }
      }
      let hit = await caches.match(key);
      if (!hit) {
        if (!request.headers.has('range')) return await fromNetwork(request, key);
        // Media asks for byte ranges: fetch the whole file once, keep it, answer the range.
        const full = await fetch(key, { cache: 'no-cache' });
        if (!full.ok || full.status !== 200) return full;
        const copy = full.clone(); caches.open(CACHE).then(cache => cache.put(key, copy)).catch(() => {});
        hit = full;
      }
      return request.headers.has('range') ? await rangeResponse(hit, request.headers.get('range')) : hit;
    } finally { if (--foreground === 0) quietSince = Date.now(); }
  })());
});

const pause = ms => new Promise(r => setTimeout(r, ms));
async function warm(full) {
  const cache = await caches.open(CACHE);
  const list = WARM.filter(([, tier]) => full || tier < 2);
  let next = 0;
  const worker = async () => {
    while (next < list.length) {
      const [path] = list[next++], key = new URL(path, scope).href;
      // Yield to the game: wait until it has not needed a file for a moment.
      while (foreground > 0 || Date.now() - quietSince < 400) await pause(250);
      try {
        if (await cache.match(key)) continue;
        const response = await fetch(key, { cache: 'no-cache' });
        if (response.ok && response.status === 200) await cache.put(key, response);
      } catch (error) {
        if (error?.name === 'QuotaExceededError') { next = list.length; return; }
        await pause(2000);
      }
    }
  };
  await Promise.all([worker(), worker()]);
}

self.addEventListener('message', event => {
  // The page checks that this cache belongs to its own release (index.html, first script).
  if (event.data?.type === 'version') { event.ports?.[0]?.postMessage(VERSION); return; }
  if (event.data?.type !== 'warm' || warming) return;
  warming = warm(event.data.full !== false).finally(() => { warming = null; });
  event.waitUntil?.(warming);
});
